  'mc-alert': {
    name: 'mc-alert',
    description: 'An alert component for MicroClub UI',
    type: 'registry:component',
    files: [
      {
        path: 'registry/ui/mc-alert.tsx',
        content:
          "'use client';\r\n\r\nimport * as React from 'react';\r\nimport { CircleAlert, CircleCheck, Popcorn } from 'lucide-react';\r\nimport { cn } from '@/lib/utils';\r\n\r\ntype AlertVariant = 'success' | 'default' | 'destructive';\r\n\r\ninterface McAlertProps extends React.HTMLAttributes<HTMLDivElement> {\r\n  variant: AlertVariant;\r\n  title: string;\r\n  description?: string;\r\n  items?: string[];\r\n}\r\n\r\nconst variantStyles: Record<AlertVariant, string> = {\r\n  success:\r\n    'border border-success rounded-lg w-fit max-w-[719px] pt-[12px] pb-[14px] pl-[12px] pr-[12px]',\r\n  default: 'border border-border rounded-lg w-fit max-w-[719px] pl-[16px] pr-3 py-3',\r\n  destructive: 'border border-destructive rounded-lg w-fit max-w-[719px] pl-[16px] pr-4 py-3',\r\n};\r\n\r\nconst titleStyles: Record<AlertVariant, string> = {\r\n  success: 'text-success font-medium text-base leading-6',\r\n  default: 'text-card-foreground font-medium text-base leading-6',\r\n  destructive: 'text-destructive font-medium text-base leading-6',\r\n};\r\n\r\nconst descStyles: Record<AlertVariant, string> = {\r\n  success: 'text-success font-normal text-sm leading-5',\r\n  default: 'text-muted-foreground font-normal text-sm leading-5',\r\n  destructive: 'text-destructive font-normal text-sm leading-5',\r\n};\r\n\r\nconst iconMap: Record<AlertVariant, React.ReactNode> = {\r\n  success: <CircleCheck className=\"size-4 shrink-0 stroke-2 text-success\" />,\r\n  default: <Popcorn className=\"size-4 shrink-0 stroke-2 text-card-foreground\" />,\r\n  destructive: <CircleAlert className=\"size-4 shrink-0 stroke-2 text-destructive\" />,\r\n};\r\n\r\nconst iconGap: Record<AlertVariant, string> = {\r\n  success: 'gap-1',\r\n  default: 'gap-3',\r\n  destructive: 'gap-3',\r\n};\r\n\r\nfunction McAlert({ variant, title, description, items, className, ...props }: McAlertProps) {\r\n  const hasSupportingContent = !!description || !!items?.length;\r\n\r\n  return (\r\n    <div\r\n      data-slot=\"mc-alert\"\r\n      data-variant={variant}\r\n      className={cn(variantStyles[variant], className)}\r\n      role=\"alert\"\r\n      {...props}\r\n    >\r\n      <div\r\n        className={cn(\r\n          'flex',\r\n          hasSupportingContent ? 'items-start' : 'items-center',\r\n          iconGap[variant]\r\n        )}\r\n      >\r\n        <div className={cn('shrink-0', hasSupportingContent && 'pt-1')}>{iconMap[variant]}</div>\r\n        <div className=\"min-w-0\">\r\n          <span className={cn('block', titleStyles[variant])}>{title}</span>\r\n\r\n          {description && <p className={cn('mt-0.5', descStyles[variant])}>{description}</p>}\r\n\r\n          {items && items.length > 0 && (\r\n            <ul className={cn('mt-0.5 list-disc pl-6', descStyles[variant])}>\r\n              {items.map((item, i) => (\r\n                <li key={i}>{item}</li>\r\n              ))}\r\n            </ul>\r\n          )}\r\n        </div>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\nexport { McAlert };\r\nexport type { McAlertProps, AlertVariant };\r\n",
        type: 'registry:component',
      },
    ],
  },
  'mc-sonner': {
    name: 'mc-sonner',
    description: 'A toast component for MicroClub UI',
    type: 'registry:component',
    files: [
      {
        path: 'registry/ui/mc-sonner.tsx',
        content:
          "'use client';\r\n\r\nimport { Toaster as SonnerComponent, toast as rawToast } from 'sonner';\r\nimport { CheckCircle2, AlertCircle } from 'lucide-react';\r\n\r\ntype ToasterProps = React.ComponentProps<typeof SonnerComponent>;\r\n\r\nconst toastIcons = {\r\n  success: <CheckCircle2 className=\"text-muted-foreground shrink-0 h-3.5 w-3.5\" />,\r\n  warning: <AlertCircle className=\"text-muted-foreground shrink-0 h-3.5 w-3.5\" />,\r\n  error: <AlertCircle className=\"text-muted-foreground  shrink-0 h-3.5 w-3.5\" />,\r\n};\r\n\r\ninterface ToastOptions {\r\n  description?: string;\r\n  action?: {\r\n    label: string;\r\n    onClick: () => void;\r\n  };\r\n}\r\n\r\nconst mcToastCustom = (\r\n  message: string,\r\n  variant?: 'success' | 'warning' | 'error',\r\n  options?: ToastOptions\r\n) => {\r\n  const Icon = variant ? toastIcons[variant] : null;\r\n\r\n  return rawToast(\r\n    <div className=\"w-full h-full flex flex-col items-start justify-center gap-0.5\">\r\n      <div className=\"flex items-center gap-1.5 w-full max-w-66.5\">\r\n        {Icon}\r\n        <span className=\"text-sm font-medium tracking-normal leading-5 text-card-foreground\">\r\n          {message}\r\n        </span>\r\n      </div>\r\n\r\n      {options?.description && (\r\n        <p className=\"text-sm font-normal tracking-normal leading-5 text-muted-foreground max-w-66.5\">\r\n          {options.description}\r\n        </p>\r\n      )}\r\n    </div>,\r\n    {\r\n      action: options?.action,\r\n    }\r\n  );\r\n};\r\n\r\nexport const toast = Object.assign(\r\n  (message: string, options?: ToastOptions) => mcToastCustom(message, undefined, options),\r\n  {\r\n    success: (message: string, options?: ToastOptions) =>\r\n      mcToastCustom(message, 'success', options),\r\n    warning: (message: string, options?: ToastOptions) =>\r\n      mcToastCustom(message, 'warning', options),\r\n    error: (message: string, options?: ToastOptions) => mcToastCustom(message, 'error', options),\r\n  }\r\n);\r\n\r\nconst McSonner = ({ ...props }: ToasterProps) => {\r\n  return (\r\n    <SonnerComponent\r\n      className=\"\"\r\n      position=\"top-center\"\r\n      toastOptions={{\r\n        unstyled: true,\r\n        classNames: {\r\n          toast:\r\n            'w-97.5 min-h-18.5 bg-background flex items-center justify-between gap-1.5 p-4 border-[1px] rounded-lg shadow-xs border-border',\r\n          actionButton:\r\n            'flex items-center justify-center bg-primary text-background text-sm py-2 px-3.5 min-w-15.5 max-w-21.5 min-h-9 rounded-[8px] shadow-xs shrink-0 cursor-pointer',\r\n        },\r\n      }}\r\n      {...props}\r\n    />\r\n  );\r\n};\r\n\r\nexport default McSonner;\r\n",
        type: 'registry:component',
      },
    ],
  },
