        content:
          "'use client';\r\n\r\nimport { PreviewCard as PreviewCardPrimitive } from '@base-ui/react/preview-card';\r\n\r\nimport { cn } from '@/lib/utils';\r\n\r\nfunction McHoverCard({ ...props }: PreviewCardPrimitive.Root.Props) {\r\n  return <PreviewCardPrimitive.Root data-slot=\"hover-card\" {...props} />;\r\n}\r\n\r\nfunction McHoverCardTrigger({ ...props }: PreviewCardPrimitive.Trigger.Props) {\r\n  return <PreviewCardPrimitive.Trigger data-slot=\"hover-card-trigger\" {...props} />;\r\n}\r\n\r\nfunction McHoverCardContent({\r\n  className,\r\n  side = 'bottom',\r\n  sideOffset = 4,\r\n  align = 'center',\r\n  alignOffset = 4,\r\n  textAlign = 'start',\r\n  imageSrc = null,\r\n  imageposition = 'top',\r\n  title,\r\n  subtitle,\r\n  description,\r\n  ...props\r\n}: PreviewCardPrimitive.Popup.Props &\r\n  Pick<PreviewCardPrimitive.Positioner.Props, 'align' | 'alignOffset' | 'side' | 'sideOffset'> & {\r\n    textAlign?: 'start' | 'center';\r\n    imageSrc?: string | null;\r\n    imageposition?: 'top' | 'bottom';\r\n    title?: string;\r\n    subtitle?: string;\r\n    description?: string;\r\n  }) {\r\n  return (\r\n    <PreviewCardPrimitive.Portal data-slot=\"hover-card-portal\">\r\n      <PreviewCardPrimitive.Positioner\r\n        align={align}\r\n        alignOffset={alignOffset}\r\n        side={side}\r\n        sideOffset={sideOffset}\r\n        className=\"isolate z-50 w-76 origin-(--transform-origin) rounded-lg bg-card p-4 text-sm text-popover-foreground shadow-md ring-inset  ring-1 ring-border flex flex-col \"\r\n      >\r\n        <div className={`${imageposition === 'top' ? 'flex-col' : 'flex-col-reverse'} flex gap-4`}>\r\n          {imageSrc && <img src={imageSrc} alt=\"Profile\" className={`w-full    `} />}\r\n          <div\r\n            className={`${textAlign === 'start' ? 'items-start' : 'items-center'} flex flex-col gap-2`}\r\n          >\r\n            {title && <h4 className=\"font-semibold text-card-foreground\">{title}</h4>}\r\n            <div\r\n              className={`${textAlign === 'start' ? 'items-start' : 'text-center'} flex flex-col`}\r\n            >\r\n              {subtitle && <p className=\" font-regular text-card-foreground\">{subtitle}</p>}\r\n              {description && <p className=\"font-regular text-card-foreground\">{description}</p>}\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <PreviewCardPrimitive.Popup\r\n          data-slot=\"hover-card-content\"\r\n          className={cn(\r\n            ' outline-hidden duration-100   ',\r\n            ' data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 ',\r\n            ' data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ',\r\n            ' data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 ',\r\n            'data-closed:zoom-out-95 gap-4',\r\n            className\r\n          )}\r\n          {...props}\r\n        />\r\n      </PreviewCardPrimitive.Positioner>\r\n    </PreviewCardPrimitive.Portal>\r\n  );\r\n}\r\n\r\nexport { McHoverCard, McHoverCardTrigger, McHoverCardContent };\r\n",
